# MLE-STAR Optimized CountGD Model
# Generated by MLE-STAR agent for lightweight deployment

import torch
import torch.nn as nn
from transformers import CLIPTextModel, CLIPTokenizer
import timm

class OptimizedMobileViT(nn.Module):
    """Optimized MobileViT backbone for CountGD"""
    
    def __init__(self):
        super().__init__()
        
        # MobileViT-XXS configuration (best candidate from MLE-STAR)
        self.backbone = timm.create_model(
            'mobilevit_xxs',
            pretrained=True,
            num_classes=0,
            global_pool=''
        )
        
        # Get feature dimension
        self.feature_dim = 320  # MobileViT-XXS output channels
        
        # Enhanced channel attention (MLE-STAR refinement)
        self.channel_attention = nn.Sequential(
            nn.AdaptiveAvgPool2d(1),
            nn.Conv2d(self.feature_dim, self.feature_dim // 4, 1),
            nn.ReLU(),
            nn.Conv2d(self.feature_dim // 4, self.feature_dim, 1),
            nn.Sigmoid()
        )
        
    def forward(self, x):
        features = self.backbone(x)
        
        # Apply channel attention
        attention = self.channel_attention(features)
        features = features * attention
        
        return features


class OptimizedCountGD(nn.Module):
    """MLE-STAR optimized CountGD model for lightweight deployment"""
    
    def __init__(self):
        super().__init__()
        
        # Optimized vision encoder
        self.vision_encoder = OptimizedMobileViT()
        
        # Lightweight text encoder
        self.text_encoder = CLIPTextModel.from_pretrained(
            "openai/clip-vit-base-patch32"
        )
        self.tokenizer = CLIPTokenizer.from_pretrained(
            "openai/clip-vit-base-patch32"
        )
        
        # Efficient fusion layers
        vision_dim = self.vision_encoder.feature_dim
        text_dim = self.text_encoder.config.hidden_size
        
        self.vision_proj = nn.Sequential(
            nn.Linear(vision_dim, 128),
            nn.ReLU(),
            nn.Dropout(0.1)
        )
        
        self.text_proj = nn.Sequential(
            nn.Linear(text_dim, 128), 
            nn.ReLU(),
            nn.Dropout(0.1)
        )
        
        # Cross-attention fusion (MLE-STAR improvement)
        self.cross_attention = nn.MultiheadAttention(
            embed_dim=128,
            num_heads=4,
            dropout=0.1,
            batch_first=True
        )
        
        self.fusion_norm = nn.LayerNorm(128)
        
        # Enhanced counting head (MLE-STAR refinement)
        self.count_head = nn.Sequential(
            nn.Linear(256, 128),
            nn.ReLU(),
            nn.Dropout(0.2),
            nn.Linear(128, 64),
            nn.ReLU(), 
            nn.Dropout(0.1),
            nn.Linear(64, 1)
        )
        
        # Auxiliary counting head for better training
        self.aux_count_head = nn.Linear(256, 1)
        
        # Grounding head
        self.grounding_head = nn.Sequential(
            nn.Conv2d(256, 64, 3, padding=1),
            nn.ReLU(),
            nn.Conv2d(64, 1, 1),
            nn.Sigmoid()
        )
        
    def forward(self, images, text_prompts):
        # Vision encoding
        vision_features = self.vision_encoder(images)  # [B, C, H, W]
        B, C, H, W = vision_features.shape
        
        # Text encoding
        if isinstance(text_prompts, (list, tuple)):
            text_inputs = self.tokenizer(
                text_prompts, 
                return_tensors="pt", 
                padding=True, 
                truncation=True,
                max_length=77
            )
            text_features = self.text_encoder(**text_inputs).last_hidden_state
        elif isinstance(text_prompts, str):
            text_inputs = self.tokenizer(
                [text_prompts], 
                return_tensors="pt", 
                padding=True, 
                truncation=True,
                max_length=77
            )
            text_features = self.text_encoder(**text_inputs).last_hidden_state
        else:
            # Already tokenized
            text_features = self.text_encoder(**text_prompts).last_hidden_state
        text_features = text_features.mean(dim=1)  # [B, text_dim]
        
        # Project features
        vision_proj = self.vision_proj(vision_features.mean(dim=[2, 3]))  # [B, 128]
        text_proj = self.text_proj(text_features)  # [B, 128]
        
        # Cross-attention fusion
        vision_attended, _ = self.cross_attention(
            vision_proj.unsqueeze(1), 
            text_proj.unsqueeze(1), 
            text_proj.unsqueeze(1)
        )
        vision_attended = vision_attended.squeeze(1)
        vision_attended = self.fusion_norm(vision_attended + vision_proj)
        
        # Fuse features
        fused_features = torch.cat([vision_attended, text_proj], dim=1)  # [B, 256]
        
        # Count prediction
        count_pred = self.count_head(fused_features)  # [B, 1]
        aux_count = self.aux_count_head(fused_features)  # [B, 1]
        
        # Grounding heatmap - upsample to match expected size
        fused_spatial = fused_features.unsqueeze(-1).unsqueeze(-1)  # [B, 256, 1, 1]
        fused_spatial = fused_spatial.expand(-1, -1, H, W)  # [B, 256, H, W]
        
        heatmap = self.grounding_head(fused_spatial)  # [B, 1, H, W]
        
        # Upsample heatmap to 14x14 to match training expectations
        if heatmap.shape[-1] != 14:
            heatmap = torch.nn.functional.interpolate(
                heatmap, size=(14, 14), mode='bilinear', align_corners=False
            )
        
        return count_pred.squeeze(-1), heatmap.squeeze(1)


# Performance utilities
def get_model_size(model):
    """Calculate model size in MB"""
    param_size = sum(p.numel() * p.element_size() for p in model.parameters())
    buffer_size = sum(b.numel() * b.element_size() for b in model.buffers())
    return (param_size + buffer_size) / (1024 ** 2)


def optimize_for_inference(model):
    """Apply inference optimizations"""
    model.eval()
    return model


def export_to_onnx(model, save_path="countgd_optimized.onnx"):
    """Export model to ONNX format"""
    model.eval()
    dummy_images = torch.randn(1, 3, 224, 224)
    dummy_text = ["count objects"]
    
    torch.onnx.export(
        model,
        (dummy_images, dummy_text),
        save_path,
        export_params=True,
        opset_version=11,
        do_constant_folding=True,
        input_names=['images', 'text'],
        output_names=['counts', 'heatmaps'],
        dynamic_axes={
            'images': {0: 'batch_size'},
            'counts': {0: 'batch_size'},
            'heatmaps': {0: 'batch_size'}
        }
    )
    print(f"Model exported to {save_path}")


def benchmark_model(model, num_runs=100):
    """Benchmark model inference speed"""
    model.eval()
    dummy_images = torch.randn(1, 3, 224, 224)
    dummy_text = ["count objects"]
    
    # Warmup
    for _ in range(10):
        with torch.no_grad():
            _ = model(dummy_images, dummy_text)
    
    # Benchmark
    import time
    start_time = time.time()
    
    for _ in range(num_runs):
        with torch.no_grad():
            _ = model(dummy_images, dummy_text)
    
    end_time = time.time()
    avg_time = (end_time - start_time) / num_runs * 1000  # ms
    
    print(f"Average inference time: {avg_time:.2f} ms")
    print(f"FPS: {1000/avg_time:.1f}")
    
    return avg_time


